// Vite resolves @airways/database via alias in vite.config.ts → packages/database/index.ts.
// pg and drizzle-orm are marked as ssr.external so they're never bundled.

export { db, getDb, guernseyTodayStr, guernseyTomorrowStr, isTerminalStatus } from '@airways/database';
export {
  flights,
  flightTimes,
  flightNotes,
  flightStatusHistory,
  weatherData,
  historicalWeather,
  airportDaylight,
  scraperLogs,
  aircraftPositions,
  airports,
  pushSubscriptions,
  notificationWatermark,
} from '@airways/database/schema';

import type { RequestHandler } from './$types';
import { getDb } from '$lib/server/db';
import { debugResponse, debugError, validateSqlQuery } from '$lib/server/debug-helpers';
import { sql } from 'drizzle-orm';

/**
 * POST /api/debug/sql
 * Body: { "sql": "SELECT * FROM flights LIMIT 10" }
 *
 * Only SELECT, EXPLAIN, SHOW, DESCRIBE, and WITH (CTE) are allowed.
 * All other statements are rejected with 403.
 * Queries have a 30-second timeout via statement_timeout.
 */
export const POST: RequestHandler = async ({ request }) => {
  const t0 = performance.now();
  try {
    const body = await request.json() as { sql?: string };
    const query = body.sql?.trim();

    if (!query) return debugError('Missing "sql" field in request body', 400);

    // Validate query (SELECT-only, no dangerous keywords)
    const validation = validateSqlQuery(query);
    if (!validation.valid) {
      return debugError(validation.error, 403);
    }

    // Get the underlying pg pool for raw SQL execution
    const d = getDb();

    // Set session-level timeout for this query only, then reset
    await d.execute(sql`SET SESSION statement_timeout = '30s'`);

    let result;
    try {
      result = await d.execute(sql`${sql.raw(query)}`);
    } finally {
      await d.execute(sql`RESET statement_timeout`);
    }

    const queryMs = performance.now() - t0;

    // Log query for audit
    const truncated = query.length > 200 ? query.substring(0, 200) + '...' : query;
    console.log(`[debug/sql] ${queryMs}ms | rows=${result.rows.length} | ${truncated}`);

    return debugResponse(result.rows, queryMs);
  } catch (err) {
    const queryMs = performance.now() - t0;
    const message = err instanceof Error ? err.message : 'Query failed';
    console.error(`[debug/sql] ERROR ${queryMs}ms | ${message}`);
    return debugError(message, 500);
  }
};

import type { RequestHandler } from './$types';
import { db, flights } from '$lib/server/db';
import { debugResponse, debugError, parsePagination } from '$lib/server/debug-helpers';
import { eq, gte, lte, and, desc, asc, ilike } from 'drizzle-orm';

/**
 * GET /api/debug/flights
 * Query params: date, status, departure_airport, arrival_airport, flight_number,
 *   airline_code, canceled, aircraft_registration, sort, order, limit, offset
 */
export const GET: RequestHandler = async ({ url }) => {
  const t0 = performance.now();

  try {
    const { limit, offset } = parsePagination(url.searchParams);
    const conditions = [];

    // Date filter — matches flight_date
    const dateParam = url.searchParams.get('date');
    if (dateParam) {
      conditions.push(eq(flights.flightDate, dateParam));
    }

    // Date range filter
    const dateFrom = url.searchParams.get('date_from');
    const dateTo = url.searchParams.get('date_to');
    if (dateFrom) conditions.push(gte(flights.flightDate, dateFrom));
    if (dateTo) conditions.push(lte(flights.flightDate, dateTo));

    // Status filter
    const statusParam = url.searchParams.get('status');
    if (statusParam) {
      conditions.push(eq(flights.status, statusParam));
    }

    // Airport filters
    const depAirport = url.searchParams.get('departure_airport');
    if (depAirport) conditions.push(eq(flights.departureAirport, depAirport.toUpperCase()));
    const arrAirport = url.searchParams.get('arrival_airport');
    if (arrAirport) conditions.push(eq(flights.arrivalAirport, arrAirport.toUpperCase()));

    // Flight number — partial match
    const flightNumber = url.searchParams.get('flight_number');
    if (flightNumber) conditions.push(ilike(flights.flightNumber, `%${flightNumber}%`));

    // Airline code
    const airlineCode = url.searchParams.get('airline_code');
    if (airlineCode) conditions.push(eq(flights.airlineCode, airlineCode.toUpperCase()));

    // Canceled flag
    const canceledParam = url.searchParams.get('canceled');
    if (canceledParam !== null) {
      conditions.push(eq(flights.canceled, canceledParam === 'true'));
    }

    // Aircraft registration
    const reg = url.searchParams.get('aircraft_registration');
    if (reg) conditions.push(eq(flights.aircraftRegistration, reg.toUpperCase()));

    // Sorting
    const sortField = url.searchParams.get('sort') ?? 'scheduled_departure';
    const sortOrder = url.searchParams.get('order') === 'asc' ? asc : desc;

    // Map sort field names to Drizzle columns
    const sortColumns: Record<string, typeof flights.scheduledDeparture> = {
      scheduled_departure: flights.scheduledDeparture,
      scheduled_arrival: flights.scheduledArrival,
      actual_departure: flights.actualDeparture,
      actual_arrival: flights.actualArrival,
      delay_minutes: flights.delayMinutes,
      flight_date: flights.flightDate,
      created_at: flights.createdAt,
      updated_at: flights.updatedAt,
    };
    const sortCol = sortColumns[sortField] ?? flights.scheduledDeparture;

    const whereClause = conditions.length > 0 ? and(...conditions) : undefined;

    const rows = conditions.length > 0
      ? await db.select().from(flights).where(whereClause).orderBy(sortOrder(sortCol)).limit(limit).offset(offset)
      : await db.select().from(flights).orderBy(sortOrder(sortCol)).limit(limit).offset(offset);

    const queryMs = performance.now() - t0;
    return debugResponse(rows, queryMs);
  } catch (err) {
    console.error('[debug/flights]', err);
    return debugError('Query failed', 500);
  }
};

import type { RequestHandler } from './$types';
import { db, flights, weatherData, airportDaylight, flightTimes, guernseyTodayStr, guernseyTomorrowStr } from '$lib/server/db';
import { debugResponse, debugError } from '$lib/server/debug-helpers';
import { and, gte, lte, inArray, or, eq, asc } from 'drizzle-orm';

const FLIGHT_COLUMNS = {
  id: flights.id,
  flightNumber: flights.flightNumber,
  departureAirport: flights.departureAirport,
  arrivalAirport: flights.arrivalAirport,
  scheduledDeparture: flights.scheduledDeparture,
  scheduledArrival: flights.scheduledArrival,
  actualDeparture: flights.actualDeparture,
  actualArrival: flights.actualArrival,
  status: flights.status,
  canceled: flights.canceled,
  aircraftType: flights.aircraftType,
  delayMinutes: flights.delayMinutes,
  flightDate: flights.flightDate,
};

/**
 * Mirrors the homepage load function's data — flight list, weather, daylight for a given date.
 * Query params: date (YYYY-MM-DD, defaults to today Guernsey time)
 */
export const GET: RequestHandler = async ({ url }) => {
  const t0 = performance.now();
  try {
    const now = new Date();
    const todayStr = guernseyTodayStr(now);
    const tomorrowStr = guernseyTomorrowStr(now);

    const dateParam = url.searchParams.get('date');
    const displayDateStr = dateParam && (dateParam === todayStr || dateParam === tomorrowStr)
      ? dateParam
      : todayStr;

    const displayFlights = await db
      .select(FLIGHT_COLUMNS)
      .from(flights)
      .where(eq(flights.flightDate, displayDateStr))
      .orderBy(flights.scheduledDeparture);

    const flightIds = displayFlights.map(f => f.id);
    const airportCodes = [...new Set(
      displayFlights.flatMap(f => [f.departureAirport, f.arrivalAirport])
    )];

    const weatherStartDate = new Date(displayDateStr + 'T00:00:00Z');
    const weatherEndDate = new Date(weatherStartDate);
    weatherEndDate.setUTCDate(weatherEndDate.getUTCDate() + 2);

    const [estimatedTimesRows, weatherRows, daylightRows] = await Promise.all([
      flightIds.length > 0
        ? db.select({ flightId: flightTimes.flightId, timeType: flightTimes.timeType, timeValue: flightTimes.timeValue })
            .from(flightTimes)
            .where(and(
              inArray(flightTimes.flightId, flightIds),
              inArray(flightTimes.timeType, ['EstimatedBlockOff', 'EstimatedBlockOn']),
            ))
        : Promise.resolve([]),
      airportCodes.length > 0
        ? db.select({
            airportCode: weatherData.airportCode, timestamp: weatherData.timestamp,
            temperature: weatherData.temperature, windSpeed: weatherData.windSpeed,
            windDirection: weatherData.windDirection, weatherCode: weatherData.weatherCode,
          })
          .from(weatherData)
          .where(and(
            inArray(weatherData.airportCode, airportCodes),
            gte(weatherData.timestamp, weatherStartDate),
            lte(weatherData.timestamp, weatherEndDate),
          ))
          .orderBy(weatherData.timestamp)
        : Promise.resolve([]),
      airportCodes.length > 0
        ? db.select({
            airportCode: airportDaylight.airportCode, date: airportDaylight.date,
            sunrise: airportDaylight.sunrise, sunset: airportDaylight.sunset,
          })
          .from(airportDaylight)
          .where(and(
            inArray(airportDaylight.airportCode, airportCodes),
            or(eq(airportDaylight.date, todayStr), eq(airportDaylight.date, tomorrowStr)),
          ))
          .orderBy(asc(airportDaylight.date))
        : Promise.resolve([]),
    ]);

    // Build estimated times map
    const estimatedTimesMap = new Map<number, { estimatedDeparture?: string; estimatedArrival?: string }>();
    for (const t of estimatedTimesRows) {
      const existing = estimatedTimesMap.get(t.flightId) ?? {};
      if (t.timeType === 'EstimatedBlockOff') existing.estimatedDeparture = t.timeValue.toISOString();
      else if (t.timeType === 'EstimatedBlockOn') existing.estimatedArrival = t.timeValue.toISOString();
      estimatedTimesMap.set(t.flightId, existing);
    }

    const flightsForDisplay = displayFlights
      .map(f => ({
        ...f,
        estimatedDeparture: estimatedTimesMap.get(f.id)?.estimatedDeparture ?? null,
        estimatedArrival: estimatedTimesMap.get(f.id)?.estimatedArrival ?? null,
      }))
      .sort((a, b) => {
        const aTime = new Date(a.estimatedDeparture ?? a.scheduledDeparture).getTime();
        const bTime = new Date(b.estimatedDeparture ?? b.scheduledDeparture).getTime();
        return aTime - bTime;
      });

    // Build weather map
    const weatherMap: Record<string, typeof weatherRows> = {};
    for (const row of weatherRows) {
      if (!weatherMap[row.airportCode]) weatherMap[row.airportCode] = [];
      weatherMap[row.airportCode].push(row);
    }

    // Build daylight map
    const daylightMap: Record<string, typeof daylightRows> = {};
    for (const row of daylightRows) {
      if (!daylightMap[row.airportCode]) daylightMap[row.airportCode] = [];
      daylightMap[row.airportCode].push(row);
    }

    const data = {
      flights: flightsForDisplay,
      weatherMap,
      daylightMap,
      displayDate: displayDateStr,
      todayStr,
      tomorrowStr,
    };

    return debugResponse([data], performance.now() - t0);
  } catch (err) {
    console.error('[debug/ui/homepage]', err);
    return debugError('Query failed', 500);
  }
};

